let P = arrange([8, A], [8, B], [8, A], [8, C], [8, A], [8, D], [8, B], [8, A])

// Two cycles per line, four lines per phrase.
let line = (a, b, c, d) => cat(n(a), n(b), n(c), n(d)).slow(2)
let cello = arrange(
  [8, line("0 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ [0 -1] ~ ~ ~", "~ ~ 3 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ 0 ~", "0 ~ 1 ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~", "~ ~ ~ ~ 4 ~ ~ ~ 3 ~ 2 ~ ~ ~ 0 ~")],
  [8, line("3 ~ ~ ~ 4 ~ ~ ~ 5 ~ ~ ~ 4 ~ 3 ~", "~ ~ 2 ~ ~ ~ 3 ~ ~ ~ 4 ~ ~ ~ ~ ~", "5 ~ ~ ~ [4 3] ~ 2 ~ ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ 2 ~ ~ ~ 1 ~ ~ ~")],
  [8, line("~ ~ 0 ~ ~ ~ 2 ~ ~ ~ 4 ~ ~ ~ 3 ~", "2 ~ ~ ~ ~ ~ 1 ~ 0 ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 3 ~ 2 ~ ~ ~ 1 ~ 0 ~ ~ ~", "-1 ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("4 ~ ~ ~ ~ ~ 3 ~ 4 ~ ~ ~ 5 ~ ~ ~", "6 ~ ~ ~ 5 ~ ~ ~ 4 ~ 3 ~ ~ ~ ~ ~", "~ ~ 2 ~ ~ ~ 4 ~ ~ ~ 3 ~ ~ ~ 2 ~", "1 ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("0 ~ ~ 1 ~ ~ 2 ~ ~ ~ ~ ~ 1 ~ ~ ~", "~ ~ 3 ~ ~ ~ ~ ~ 2 ~ 1 ~ 0 ~ ~ ~", "~ ~ ~ ~ 4 ~ ~ 3 ~ ~ 2 ~ ~ ~ ~ ~", "3 ~ ~ ~ 2 ~ ~ ~ 1 ~ ~ ~ 0 ~ ~ ~")],
  [8, line("~ ~ ~ ~ 2 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ 0 ~ ~ ~ ~ ~ ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("2 ~ ~ 3 ~ ~ 4 ~ ~ 5 ~ ~ 4 ~ ~ ~", "~ ~ 3 ~ ~ ~ 5 ~ ~ ~ 6 ~ ~ ~ 5 ~", "4 ~ ~ ~ 3 ~ ~ 2 ~ ~ 1 ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ 1 ~ ~ ~ 0 ~")],
  [8, line("0 ~ ~ ~ 2 ~ 1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ 0 ~ ~ ~ -1 ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ 0 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
)

// the harp answers where the cello rests: a different pick in each phrase
let touch = arrange(
  [8, line("~ ~ ~ 4 ~ ~ 2 ~ ~ ~ ~ ~ ~ 6 ~ ~", "~ ~ ~ ~ ~ 3 ~ ~ ~ ~ 5 ~ ~ ~ ~ ~", "~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 3 ~", "~ ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 4 ~ ~ ~ ~")],
  [8, line("~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 5 ~ ~ ~", "~ ~ ~ 2 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~", "~ ~ 6 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 2 ~", "~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~ 5 ~ ~ ~")],
  [8, line("~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~ ~", "~ 6 ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~", "~ ~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~")],
  [8, line("~ ~ 2 ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~", "~ ~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~", "6 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~")],
  [8, line("~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ ~ ~", "~ 3 ~ ~ ~ ~ 5 ~ ~ ~ ~ ~ ~ ~ 4 ~", "~ ~ ~ ~ ~ 2 ~ ~ ~ ~ ~ ~ 4 ~ ~ ~", "~ ~ 6 ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~")],
  [8, line("~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 2 ~ ~ ~ ~ ~", "~ ~ ~ 6 ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~")],
  [8, line("~ 2 ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~", "~ ~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~", "~ ~ 4 ~ ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 5 ~", "~ ~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~")],
  [8, line("~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
)

stack(
  // 0: low strings and the cello
  chord(P).voicing().mode("below:g3")
    .s("supersaw").unison(2).detune(.2).attack(2).clip(.9).release(.3).gain(.16)
    .lpf(sine.range(500, 1100).slow(32)).room(.9).roomsize(6).orbit(2),
  cello.scale("d3:aeolian")
    .s("sawtooth").attack(.25).release(1.6).gain(.5).vib("5.2:.2")
    .lpf(900).lpenv(2).lpa(.3).lpd(.8).room(.8).roomsize(6).orbit(2),
  // 1: a harp touches the chord, high and far
  layer(1, touch.chord(P).voicing().mode("above:d4")
    .s("harp").gain(.4).room(.9).roomsize(6).orbit(2))
).postgain(.85)
`,ty=`// clash-of-standards - A dorian, 140 bpm. mood: action, epic.
// A 4v4 skirmish. Driving war drums, a string ostinato in sixteenths, short
// brass stabs. Even the calm level keeps moving: this is a fight track.
// Fourteen sections of eight cycles (3m12s before it repeats): four chord
// journeys, and the bass riff, the stabs and the whistle never repeat a bar.
setcpm(140 / 4)

let A = "<Am7 D7 Am7 G^7 Am7 D7 Em7 Am7>"
let B = "<Am7 G^7 C^7 D7 Am7 Em7 D7 G^7>"
let C = "<Em7 Am7 D7 G^7 C^7 D7 Bm7 Em7>"
let D = "<Am7 C^7 G^7 D7 Em7 G^7 D7 Am7>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, B], [8, C], [8, D], [8, B], [8, A])

// the whistle's tune: eight cycles
let tune = "<[7 ~ 6 4 ~ 4 2 ~] [4 ~ 2 0 ~ 0 2 4] [6 ~ 4 2 ~ 2 0 ~] [2 ~ 4 6 ~ 7 6 4] [7 ~ 7 6 ~ 4 6 7] [4 ~ 6 4 ~ 2 0 ~] [2 4 6 4 2 ~ 0 ~] [0 ~ ~ 2 4 ~ ~ ~]>"
let whistle = arrange([8, tune], [8, tune.add(2)], [8, tune.rev()], [8, tune.add(-2)], [8, tune.add(3)],
  [8, tune.rev().add(2)], [8, tune], [8, tune.add(-2).rev()], [8, tune.add(2).rev()], [8, tune.add(3)],
  [8, tune.rev()], [8, tune.add(-2)], [8, tune.add(2)], [8, tune])

stack(
  // 0: sixteenth-note string pulse on the root, a bass line
  n("0 0 [0 7] 0 0 [0 7] 0 0 0 [0 7] 0 [4 3] 0 0 [2 0]".add("<0 0 1 0 0 0 -1 0 0 2 0 0 -2 0 0 3>")).scale("a2:dorian")
    .s("sawtooth").decay(.1).sustain(0).release(.05).gain(.45).lpf(ref(() => 600 + INTENSITY * 500)).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:e4")
    .s("supersaw").unison(2).detune(.2).attack(.1).clip(.9).release(.15).gain(.22)
    .lpf(1400).room(.4).roomsize(6).orbit(2),
  s("timp:1 ~ ~ ~ timp:1 ~ ~ ~").gain(.5).room(.3),
  // 1: frame drums drive the offbeat, the lute stabs
  layer(1, stack(
    s("~ frame:0 ~ frame:2 ~ frame:0 ~ frame:2").gain(.45),
    n("<0 ~ 2 ~>*4").chord(P).voicing().mode("above:a3").s("strum").gain(.5).room(.3))),
  // 2: war drums, snare, brass stabs
  layer(2, stack(
    s("taiko:0 ~ taiko:1 taiko:0 ~ taiko:1 taiko:0 ~").gain(.8).room(.3),
    s("~ ~ snare:0 ~ ~ ~ snare:1 ~").gain(.4),
    n("[0 ~ ~ 0 ~ ~ 2 ~] [~ ~ 4 ~ ~ 2 ~ ~]".add("<0 2 0 3 4 0 -2 0>")).scale("a3:dorian")
      .s("sawtooth").attack(.01).release(.2).gain(.5).lpf(1000).lpenv(2).lpd(.15).room(.3).roomsize(6).orbit(2))),
  // 3: crash on the bar, the whistle screams the tune
  layer(3, stack(
    s("crash:1 ~ ~ ~ ~ ~ ~ ~").gain(.35),
    n(whistle).scale("a3:dorian")
      .s("whistle").gain(.5).attack(.02).release(.3).lpf(2800).room(.4).roomsize(6).orbit(2)))
).postgain(.31)
`,ny=`// ember-deep - C aeolian with a phrygian bII (Db) on purpose, 100 bpm.
// mood: dark, action. Volcanic menace: low brass, anvil hits, a grinding ostinato
// that never quite resolves. Db is the heat, and the only note outside the key.
// Ten sections of eight cycles (3m12s before it repeats): four chord
// journeys, and the ostinato and the brass stabs keep changing their notes.
setcpm(100 / 4)

let A = "<Cm9 Db^7 Cm9 Gm7 Fm9 Db^7 Ab^7 Bb>"
let B = "<Fm9 Cm9 Db^7 Cm9 Gm7 Ab^7 Db^7 Bb>"
let C = "<Cm9 Gm7 Ab^7 Bb Cm9 Fm9 Db^7 Gm7>"
let D = "<Db^7 Cm9 Bb Ab^7 Fm9 Gm7 Cm9 Db^7>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, C])

stack(
  // 0: low brass swells and the sub
  chord(P).voicing().mode("below:g3")
    .s("sawtooth").attack(.7).clip(.9).release(.2).gain(.3)
    .lpf(500).lpenv(3).lpa(.5).lpd(1.2).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(1)).s("sine").attack(.05).release(1.2).gain(.4),
  s("anvil:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.35).room(.6).roomsize(6).orbit(2),
  // 1: the grinding ostinato
  layer(1, n("0 0 [0 1] 0 0 3 0 [0 1]".fast(2).add("<0 0 0 0 0 0 3 0 0 0 0 0 -2 0 3 1>")).scale("c2:aeolian")
      .s("sawtooth").decay(.12).sustain(.2).release(.05).gain(.6)
      .lpf(sine.range(300, 900).slow(8)).lpq(6).distort("1:.4")),
  // 2: war drums and anvil
  layer(2, stack(
    s("taiko:0 ~ ~ taiko:1 ~ taiko:0 ~ ~").gain(.8).room(.4),
    s("anvil:1 ~ ~ ~ ~ anvil:2 ~ ~").gain(.4).room(.5))),
  // 3: brass stabs and the choir
  layer(3, stack(
    n("0 ~ ~ 0 ~ ~ 4 ~".add("<0 0 2 0 3 0 -1 0 4 2 0 0 -2 0 3 2>")).scale("c3:aeolian").s("sawtooth").attack(.02).release(.1).gain(.4)
      .lpf(1000).lpenv(2).lpd(.3).room(.4).roomsize(6).orbit(2),
    chord(P).voicing().mode("below:c5").s("sawtooth").lpq(4).attack(.4).clip(.9).release(.2).gain(.2)
      .lpf(2000).room(.8).roomsize(6).orbit(2)))
).postgain(.27)
`,ry=`// first-light - D lydian, 76 bpm. mood: atmospheric, adventurous.
// Pastoral morning before everything went wrong: harp over warm strings, the
// raised 4th (G#) as hope. Level 0 is the morning, level 1 the walk.
// Eight phrases of eight cycles (3m22s before it repeats): the chords change
// in four ways.
setcpm(76 / 4)

let A = "<D^9 E Bm7 A D^9 E F#m7 A>"
let B = "<Bm7 C#m7 D^9 E F#m7 Bm7 E A>"
let C = "<D^9 F#m7 Bm7 C#m7 D^9 E A D^9>"
let D = "<F#m7 Bm7 E A D^9 C#m7 Bm7 E>"
// phrase order: A B A C | A' D B A
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, A], [8, D], [8, B], [8, A])

stack(
  // 0: strings and a soft bass
  chord(P).voicing().mode("below:a4")
    .s("supersaw").unison(3).detune(.25).attack(1.4).clip(.9).release(.25).gain(.18)
    .lpf(sine.range(700, 1800).slow(16)).room(.8).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.08).release(1.2).gain(.45),
  // 1: the harp starts walking, a frame drum keeps time far off
  layer(1, stack(
    n("0 2 4 [5 4] 2 4 6 [4 2]").chord(P).voicing().mode("above:d3")
      .s("harp").gain(.55).room(.6).roomsize(6).orbit(2),
    s("frame:3 ~ ~ ~ frame:3 ~ [~ frame:3] ~").gain(.35).room(.4)))
).postgain(.4)
`,iy=`// glass-dunes - D phrygian dominant ("spanish" in Strudel scale names), 66 bpm. mood: epic, mysterious.
// A warm, wide desert at dusk: a low drone, a soft triangle pad and a plucked
// harp that tells four slow tales over it. Nothing blows and nothing is higher
// than B4 except a few far bells. Later layers add a strummed figure, a low
// triangle answer and a muffled drum.
// Eight sections of eight cycles (about 3m52s per pass): the pad walks
// four roads and the harp sings a different tale on each.
setcpm(66 / 4)

let A = "<D Eb D Gm D Eb Gm D>"
let B = "<Gm D Eb D Gm Eb D D>"
let C = "<D Gm Eb D Gm Eb Gm D>"
let E = "<Eb D Gm Gm D Eb D D>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, E], [8, B], [8, C], [8, A])

// four tales, one bar of eight steps each, over two cycles
let tale1 = "0 ~ 2 ~ 1 ~ 0 ~ | ~ 2 ~ 3 ~ 4 ~ 2 ~"
let tale2 = "4 ~ 3 ~ 2 ~ ~ 1 | 0 ~ ~ 2 ~ 1 ~ ~"
let tale3 = "~ 0 ~ 1 ~ 3 ~ 2 | 4 ~ 4 ~ 3 ~ 2 ~"
let tale4 = "2 ~ ~ 4 ~ 3 ~ ~ | 1 ~ 2 ~ 0 ~ ~ ~"
let walk = cat(tale1, tale2, tale3, tale4).slow(2)
let lead = arrange([8, walk], [8, walk.add(-2)], [8, walk.rev()], [8, walk.add(1)],
  [8, walk.add(-2)], [8, walk.rev().add(1)], [8, walk.add(1).rev()], [8, walk])

stack(
  // 0: drone, pad and the harp
  note("d1").s("sine").attack(2).release(3).gain(.5),
  note("d2").s("triangle").attack(2).release(3).gain(.3),
  chord(P).voicing().mode("below:a4")
    .s("triangle").attack(1.2).release(2.5).gain(.2)
    .lpf(1400).room(.9).roomsize(6).orbit(2),
  n(lead).scale("d4:spanish")
    .s("harp").gain(.6).release(1.2).room(.8).roomsize(6).orbit(2),
  // 1: a strummed figure and sparse far bells
  layer(1, stack(
    chord(P).voicing().mode("below:a4").segment(4).s("strum").gain(.22).room(.5).roomsize(6).orbit(2),
    note("<d5 ~ a5 ~ f#5 ~ c6 ~>").s("bells").gain(.2).room(.9).roomsize(6).orbit(2))),
  // 2: a low triangle answers the harp, a muffled drum under it
  layer(2, stack(
    s("taiko:0 ~ ~ ~ ~ ~ taiko:1 ~").gain(.5).lpf(900).room(.5),
    n(lead.add(-7)).scale("d4:spanish").s("triangle")
      .attack(.05).release(.8).gain(.35).room(.6).roomsize(6).orbit(2)))
).postgain(.33)
`,ay=`// hall-of-champions - D aeolian with a harmonic-minor V (C# in the A chord), 128 bpm.
// mood: epic, action. The PvP hall: heroic, ceremonial, then all-out. Timpani
// ostinato and full strings from level 0, a brass melody at level 2, the choir
// and war drums at level 3. C# is the raised 7th, the only note outside the key.
// Thirteen sections of eight cycles (3m15s before it repeats): four chord
// journeys, and the brass sings a new verse over each.
setcpm(128 / 4)

let A = "<Dm Bb^7 C Dm Gm7 Bb^7 A Dm>"
let B = "<Gm7 Dm Bb^7 C Dm F A Dm>"
let C = "<Bb^7 C Dm A Bb^7 F Gm7 A>"
let D = "<Dm F C Gm7 Bb^7 C A Dm>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, B], [8, C], [8, D], [8, A])

// the brass verse: eight cycles
let verse = "<[4@2 3 2@2 0 1 2] [4@2 5 4@2 2 1 0] [4@2 3 2@2 0 2 4] [5@3 4 3 2 ~ 0] [2@2 3 4@2 5 4 2] [5@2 6 5@2 4 3 2] [4@2 2 0@2 1 2 3] [0@6 ~ ~]>"
let brass = arrange([8, verse], [8, verse.add(2)], [8, verse.rev()], [8, verse.add(-2)], [8, verse.add(4)],
  [8, verse.rev().add(2)], [8, verse], [8, verse.add(-2).rev()], [8, verse.add(2).rev()], [8, verse.add(4)],
  [8, verse.rev()], [8, verse.add(-2)], [8, verse])

stack(
  // 0: the full strings and the timpani ostinato
  chord(P).voicing().mode("below:f4")
    .s("supersaw").unison(1).attack(.3).clip(.9).release(.15).gain(.25)
    .lpf(ref(() => 900 + INTENSITY * 700)).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("sawtooth").attack(.02).clip(.9).release(.2).gain(.25).lpf(300),
  s("timp:0 ~ [~ timp:0] timp:0 ~ ~ [timp:1 timp:0] ~").gain(.7).room(.35),
  // 1: strings in eighths, a ceremonial bell
  layer(1, stack(
    n("0 1 2 1 0 1 2 3").chord(P).voicing().mode("above:d3")
      .s("sawtooth").attack(.01).decay(.15).sustain(.3).release(.1).gain(.35).lpf(1800).room(.4).roomsize(6).orbit(2),
    s("bells:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.35).room(.8).roomsize(6).orbit(2))),
  // 2: the brass melody, snare and cymbal
  layer(2, stack(
    n(brass).scale("d4:aeolian")
      .s("sawtooth").attack(.04).release(.15).gain(.5).lpf(500).lpenv(3).lpa(.05).lpd(.5).room(.5).roomsize(6).orbit(2),
    s("~ snare:1 ~ snare:1").gain(.35).room(.3),
    s("crash:0 ~ ~ ~ ~ ~ ~ ~").slow(4).gain(.3))),
  // 3: the choir, doubled war drums
  layer(3, stack(
    chord(P).voicing().mode("below:d5").s("triangle").attack(.2).clip(.9).release(.15).gain(.3)
      .room(.8).roomsize(6).orbit(2),
    s("taiko:0 ~ taiko:1 taiko:0 ~ taiko:1 ~ taiko:0").gain(.5).room(.4)))
).postgain(.28)
`,oy=`// jungle-veil - E dorian, 84 bpm. mood: mysterious, atmospheric.
// Overgrown, alive, watched. Pizzicato that never lands on the same beat twice
// (7 and 5 steps against a 4-beat bar), hand percussion, a breathy wooden flute.
// Nine sections of eight cycles (3m25s before it repeats): the flute turns its
// call over, up and backwards while the chords wander four different paths.
setcpm(84 / 4)

let A = "<Em9 A7 D^7 Bm7 Em9 A7 Gadd9 Bm7>"
let B = "<Gadd9 D^7 Em9 Bm7 F#m7 Em9 A7 D^7>"
let C = "<Em9 Bm7 Gadd9 A7 Em9 D^7 F#m7 Bm7>"
let D = "<Bm7 Gadd9 D^7 A7 Em9 F#m7 Bm7 Em9>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D])

// the flute call: four lines of two cycles
let call = cat(
  "0 ~ ~ 2 [4 3] ~ 1 ~ ~ ~ 0 ~ ~ ~ ~ ~",
  "~ ~ 4 ~ ~ 5 ~ 4 ~ ~ 2 ~ [3 2] ~ ~ ~",
  "2 ~ ~ ~ 4 ~ [6 5] ~ 4 ~ ~ ~ 2 ~ ~ ~",
  "~ ~ 0 ~ 1 ~ 2 ~ ~ ~ ~ ~ 0 ~ ~ ~").slow(2)
let flute = arrange([8, call], [8, call.add(2)], [8, call.rev()], [8, call.add(-2)], [8, call.add(4)],
  [8, call.rev().add(2)], [8, call], [8, call.add(-2).rev()], [8, call.add(2)])

stack(
  // 0: the humid bed - a low drone, a held chord, the flute calling
  note("e2").s("triangle").attack(1).release(2).gain(.5).lpf(400),
  chord(P).voicing().mode("below:g4")
    .s("supersaw").unison(2).detune(.3).attack(1.6).clip(.9).release(.25).gain(.15)
    .lpf(sine.range(500, 1400).slow(12)).room(.85).roomsize(6).orbit(2),
  n(flute).scale("e3:dorian")
    .s("recorder").gain(.6).attack(.12).release(.7).lpf(2800).room(.8).roomsize(6).orbit(2),
  // 1: pizzicato in seven, hand drum in five - the jungle moves
  layer(1, stack(
    n("0 2 4 1 3 5 2").chord(P).voicing().mode("above:e3").fast(4/7*4/4)
      .s("pizz").gain(.7).room(.5).roomsize(6).orbit(2),
    s("frame:3 ~ frame:2 ~ frame:3").fast(4/5*1).gain(.4).room(.4).pan(.3))),
  // 2: a slow war drum and a lute under the flute
  layer(2, stack(
    s("taiko:1 ~ ~ ~ ~ ~ taiko:0 ~").gain(.7).lpf(500).room(.5),
    n("<0 ~ ~ 4 ~ 2 ~ ~>*2".add("<0 0 -1 0 2 0 0 -2>")).scale("e3:dorian").s("strum").gain(.5).room(.5)))
).postgain(.35)
`,sy=`// last-stand - B phrygian, 150 bpm. mood: tense, dark.
// Back to the wall. A heartbeat sub pulse that never stops, strings that tremble
// faster as intensity climbs, a filter that opens with every level.
// Fifteen sections of eight cycles (3m12s before it repeats): the held chords
// take four dark roads and the rising line climbs a new stair each time.
setcpm(150 / 4)

let A = "<Bm Cadd9 Bm Gadd9 Bm Cadd9 Am7 Bm>"
let B = "<Em Bm Cadd9 Bm Gadd9 Am7 Cadd9 Bm>"
let C = "<Bm D Gadd9 Cadd9 Bm Em Am7 Bm>"
let D = "<Cadd9 Bm Am7 Gadd9 Em Bm Cadd9 Bm>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D], [8, A], [8, B], [8, C], [8, D], [8, B], [8, A])

// the rising line: eight cycles
let stair = "<[0 ~ 1 ~ 0 ~ 2 ~] [4 ~ 3 ~ 2 ~ 1 ~] [0 ~ 2 ~ 4 ~ 2 ~] [3 ~ 2 ~ 1 ~ 0 ~] [0 ~ 1 ~ 3 ~ 1 ~] [5 ~ 4 ~ 2 ~ 1 ~] [2 ~ 1 ~ 0 ~ 1 ~] [4 ~ 5 ~ 4 ~ 2 ~]>"
let line = arrange([8, stair], [8, stair.add(1)], [8, stair.rev()], [8, stair.add(3)], [8, stair.add(-1)],
  [8, stair.rev().add(2)], [8, stair], [8, stair.add(2).rev()], [8, stair.add(4)], [8, stair.rev()],
  [8, stair.add(1)], [8, stair.add(-1).rev()], [8, stair.add(3)], [8, stair.rev().add(1)], [8, stair])

stack(
  // 0: the heartbeat and a dark held chord
  note("b1 ~ ~ ~ b1 ~ [b1 ~] ~").s("sine").decay(.25).sustain(0).gain(.5).lpf(150),
  chord(P).voicing().mode("below:d4")
    .s("sawtooth").attack(.8).clip(.9).release(.12).gain(.22)
    .lpf(ref(() => 400 + INTENSITY * 900)).room(.7).roomsize(6).orbit(2),
  // 1: tremolo strings (sixteenth gates), taiko on the heart
  layer(1, stack(
    n("0 2 4").chord(P).voicing().mode("above:b3").struct("x*16")
      .s("supersaw").unison(2).detune(.2).decay(.1).sustain(.6).release(.05).gain(.3)
      .lpf(ref(() => 600 + INTENSITY * 800)).roomsize(6).orbit(2),
    s("taiko:1 ~ ~ ~ taiko:1 ~ ~ ~").gain(.6).room(.3))),
  // 2: war drums and the rising line
  layer(2, stack(
    s("taiko:0 taiko:1 ~ taiko:0 taiko:1 ~ taiko:0 taiko:1").gain(.7).room(.3),
    n(line).scale("b3:phrygian")
      .s("sawtooth").attack(.02).release(.3).gain(.45).lpf(1000).lpenv(2).lpd(.25).room(.4).roomsize(6).orbit(2))),
  // 3: choir, cymbal swell, everything open
  layer(3, stack(
    chord(P).voicing().mode("below:f#5").s("sawtooth").lpq(4).attack(.3).clip(.9).release(.12).gain(.2).lpf(2600).room(.7).roomsize(6).orbit(2),
    s("swell:0 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.3),
    s("snare:1*8").gain(.18)))
).postgain(.29)
`,cy=`// northern-pass - G mixolydian, 96 bpm. mood: adventurous, epic.
// Setting out over snowy mountains: a horn call, a striding bass, a frame drum
// and a tin whistle. Level 1 adds the lute, level 2 the full march.
// Ten sections of eight cycles (3m20s before it repeats): four chord journeys,
// and the horn call climbs, turns and answers itself section by section.
setcpm(96 / 4)

let A = "<G F C G G F Dm F>"
let B = "<C G F C Em F G Dm>"
let C = "<Am F C G Am Em F G>"
let D = "<Dm C F G Dm Am F G>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, A], [8, C], [8, D], [8, A])

// the horn call: eight cycles, a rest of a bar after each call
let call = "<[0@3 4@2 ~ 2 ~] ~ [2@3 1@2 ~ 0@2] ~ [4@3 5@2 ~ 7 ~] ~ [5@3 4@2 ~ 2 ~] [2@2 1@2 0@4]>"
let horn = arrange([8, call], [8, call.add(2)], [8, call.rev()], [8, call.add(-2)], [8, call.add(4)],
  [8, call.rev().add(2)], [8, call], [8, call.add(-2).rev()], [8, call.add(2)], [8, call.rev().add(-2)])

stack(
  // 0: open fifths in the strings, the striding bass, the horn call
  chord(P).voicing().mode("below:d4")
    .s("supersaw").unison(2).detune(.2).attack(.6).clip(.9).release(.2).gain(.17)
    .lpf(1500).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.02).decay(.25).sustain(.4).release(.2).gain(.5)
    .struct("x ~ x ~ x x x x"),
  n(horn).scale("g3:mixolydian")
    .s("sawtooth").attack(.08).release(.3).gain(.4)
    .lpf(500).lpenv(3).lpa(.12).lpd(.6).room(.7).roomsize(6).orbit(2),
  s("frame:1 ~ ~ ~ frame:1 ~ ~ ~").gain(.45).room(.3),
  // 1: the lute joins, the whistle answers the horn
  layer(1, stack(
    n("~ 0 ~ 2 ~ 0 ~ 2").chord(P).voicing().mode("above:g3")
      .s("strum").gain(.55).room(.4),
    n("~ ~ ~ ~ 4 [5 4] 2 ~ ~ ~ ~ ~ 2 [3 2] 0 ~".slow(2).add("<0 0 -1 0 -2 0 -3 0>"))
      .scale("g4:mixolydian")
      .s("whistle").gain(.45).attack(.03).release(.15).lpf(2800).room(.5).roomsize(6).orbit(2))),
  // 2: the march
  layer(2, stack(
    s("timp:0 ~ ~ timp:0 ~ ~ timp:0 ~").gain(.55).room(.3),
    s("~ ~ frame:0 ~ ~ ~ frame:0 ~").gain(.4),
    n("<0 0 0 0 0 0 0 0>*2".add("<0 0 -1 0 0 0 -2 0>")).scale("g3:mixolydian")
      .s("sawtooth").attack(.05).release(.15).gain(.18).lpf(1000).lpenv(2).lpd(.3).roomsize(6).orbit(2)))
).postgain(.45)
`,ly=`// vibe-wars - E aeolian, 100 bpm. mood: adventurous, epic.
// The title theme. Horns rise a fifth and an octave in the first bar, so the
// flash lands on a statement; the B7 turns it back to the top without a seam.
// One level: the splash plays no intensity ramp, so level 0 is the whole theme.
// Four sections of twenty cycles (3m12s) carry the theme up and down the scale.
setcpm(100 / 4)

let P = "<Em C^7 Am7 B7>"
let theme = "<[0@2 4@2 7@4] [7@2 6@2 5@2 4@2] [3@2 5@2 4 3 2 1] [1@2 2 3@2 4@3]>"

let tune = arrange([20, theme], [20, theme.add(2)], [20, theme.add(4)], [20, theme.add(-2)])

stack(
  chord(P).voicing().mode("below:g4")
    .s("sawtooth").lpq(4).attack(.4).clip(.9).release(.2).gain(.2)
    .lpf(1800).room(.8).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:e4")
    .s("supersaw").unison(1).attack(.4).clip(.9).release(.2).gain(.2).lpf(1500).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.04).clip(.9).release(.2).gain(.5),
  n(tune).scale("e3:minor")
    .s("sawtooth").attack(.06).release(.3).gain(.5)
    .lpf(500).lpenv(3).lpa(.08).lpd(.5).room(.6).roomsize(6).orbit(2),
  s("timp:2 ~ timp:2 ~ timp:2 ~ timp:2 timp:2").gain(.4).room(.3),
  s("taiko:1 ~ ~ ~ taiko:1 ~ ~ ~").gain(.35),
  s("crash:0 ~ ~ ~ ~ ~ ~ ~").slow(4).gain(.3),
  n("0 2 4 2 0 2 4 7").chord(P).voicing().mode("above:e3").s("harp").gain(.35).room(.6).roomsize(6).orbit(2)
).postgain(.335)
`,uy=`// victors-hymn - Bb major, 108 bpm. mood: triumphant, epic.
// Banners up. A brass chorale over choir and bells: noble, not cheesy. Level 0
// is the hymn, level 1 adds the timpani roll and the cymbal.
// Eleven sections of eight cycles (3m16s before it repeats): four chord
// journeys, and the brass sings a new verse of the hymn over each.
setcpm(108 / 4)

let A = "<Bb F Gm7 Eb^7 Bb F Eb F>"
let B = "<Gm7 Eb^7 Bb F Cm7 Gm7 F Bb>"
let C = "<Eb^7 Bb F Gm7 Eb^7 Cm7 F Bb>"
let D = "<Bb Dm7 Eb^7 F Gm7 Cm7 F Bb>"
let P = arrange([8, A], [8, B], [8, A], [8, C], [8, D], [8, B], [8, C], [8, A], [8, D], [8, B], [8, A])

// the hymn: eight cycles
let hymn = "<[2@2 4 3@2 2 1] [0@2 1 2@4] [4@2 5 4@2 2 1] [0@6 ~ ~] [4@2 5 6@2 4 3 2] [7@3 6 5 4 ~ 2] [5@2 4 2@2 3 4 5] [0@6 ~ ~]>"
let tune = arrange([8, hymn], [8, hymn.add(2)], [8, hymn.rev()], [8, hymn.add(-2)], [8, hymn.add(3)],
  [8, hymn.rev().add(2)], [8, hymn.add(-2).rev()], [8, hymn], [8, hymn.add(4)], [8, hymn.rev()], [8, hymn])

stack(
  // 0: choir and strings hold the chord, the brass sings the tune
  chord(P).voicing().mode("below:f4")
    .s("sawtooth").lpq(4).attack(.5).clip(.9).release(.2).gain(.2)
    .lpf(2200).room(.85).roomsize(6).orbit(2),
  chord(P).voicing().mode("below:d4")
    .s("supersaw").unison(1).attack(.5).clip(.9).release(.2).gain(.22).lpf(1600).room(.6).roomsize(6).orbit(2),
  note(P.rootNotes(2)).s("triangle").attack(.04).clip(.9).release(.2).gain(.5),
  n(tune).scale("bb3:major")
    .s("sawtooth").attack(.1).release(.3).gain(.5)
    .lpf(500).lpenv(3).lpa(.1).lpd(.6).room(.7).roomsize(6).orbit(2),
  s("bells:1 ~ ~ ~ ~ ~ ~ ~").slow(2).gain(.3).room(.9).roomsize(6).orbit(2),
  // 1: banners snap in the wind
  layer(1, stack(
    s("timp:2*8").gain(.35).room(.3),
    s("crash:0 ~ ~ ~ ~ ~ ~ ~").slow(4).gain(.3),
    n("0 2 4 2 0 2 4 7").chord(P).voicing().mode("above:bb3").s("harp").gain(.4).room(.6).roomsize(6).orbit(2)))
).postgain(.335)
